// GENERATED by shape.py — do not edit; the shape lives in shape.py.
// The Rust twin of the load/alloc workload triplet (row 18): the SAME
// window count, item counts, batch structure, and windowed-mean timing.
fn build_corpus() -> Vec<String> {
    let tpl = [
        "the quick brown fox jumps over the lazy dog",
        "hybrid emits plain go and the checker classifies the boundary",
        "a string with  several  double  spaces to split",
        "queue shapes must match across languages or the gap is fake",
    ];
    let mut items = Vec::with_capacity(2000);
    for i in 0..2000 {
        items.push(format!("{} {} {}", tpl[i % tpl.len()], i, i * 7));
    }
    items
}

fn split_ws(s: &str) -> Vec<&str> {
    s.split(' ').collect()
}

fn pct(sorted: &[i64], p: usize) -> i64 {
    let n = sorted.len();
    let rank = (p * n + 99) / 100;
    let mut idx = if rank > 0 { (p * n + 99) / 100 - 1 } else { 0 };
    if idx >= n {
        idx = n - 1;
    }
    sorted[idx]
}

fn main() {
    let alphabet: Vec<u8> = vec![1u8, 2u8, 3u8, 4u8, 5u8, 6u8, 7u8, 8u8, 9u8, 10u8, 11u8, 12u8, 13u8, 14u8, 15u8, 16u8, 17u8, 18u8, 19u8, 20u8, 21u8, 22u8, 23u8, 24u8, 25u8, 26u8, 27u8, 28u8, 29u8, 30u8, 31u8, 32u8, 33u8, 34u8, 35u8, 36u8, 37u8, 38u8, 39u8, 40u8, 41u8, 42u8, 43u8, 44u8, 45u8, 46u8, 47u8, 48u8, 49u8, 50u8, 51u8, 52u8, 53u8, 54u8, 55u8, 56u8, 57u8, 58u8, 59u8, 60u8, 61u8, 62u8, 63u8, 64u8];

    // alloc — the SAME queue shape: 32 batches x 128 items x 960 bytes.
    let mut alloc_means: Vec<i64> = Vec::with_capacity(100);
    for _ in 0..100 {
        let t0 = std::time::Instant::now();
        for _b in 0..32 {
            for j in 0..128 {
                let mut item: Vec<u8> = Vec::new();
                for k in 0..960 {
                    item.push(alphabet[(j + k) % alphabet.len()]);
                }
                std::hint::black_box(&item);
            }
        }
        alloc_means.push(t0.elapsed().as_nanos() as i64 / (32 * 128));
    }
    alloc_means.sort_unstable();
    println!(
        "alloc p50={}ns p99={}ns mean={:.1}ns n={}",
        pct(&alloc_means, 50),
        pct(&alloc_means, 99),
        alloc_means.iter().sum::<i64>() as f64 / alloc_means.len() as f64,
        alloc_means.len()
    );

    // load — the SAME corpus + split + count shape.
    let items = build_corpus();
    let mut load_means: Vec<i64> = Vec::with_capacity(100);
    for _ in 0..100 {
        let t0 = std::time::Instant::now();
        let mut tokens = 0usize;
        let mut chars = 0usize;
        for it in &items {
            tokens += split_ws(it).len();
            chars += it.len();
        }
        std::hint::black_box((tokens, chars));
        load_means.push(t0.elapsed().as_nanos() as i64 / 2000);
    }
    load_means.sort_unstable();
    println!(
        "load p50={}ns p99={}ns mean={:.1}ns n={}",
        pct(&load_means, 50),
        pct(&load_means, 99),
        load_means.iter().sum::<i64>() as f64 / load_means.len() as f64,
        load_means.len()
    );
}
